{
  "name": "Minitel 终端",
  "name_en": "Minitel terminal",
  "manufacturer": "",
  "description": "Minitel 是一种带显示屏和键盘的法国语音视频文本终端，可通过 TTL 串口与计算机通信。它适用于显示文本与简单图形、接收键盘输入、切换工作模式以及进行复古终端交互、通信协议演示和人机界面实验。",
  "description_en": "A Minitel is a French videotex terminal with a screen and keyboard that communicates with a computer over a TTL serial link. It is used to display text and simple graphics, accept keyboard input, switch operating modes, and support retro terminal interaction, communication protocol demonstrations, and human-machine interface experiments.",
  "tag_hints": [
    "Minitel",
    "videotex terminal",
    "TTL serial communication",
    "retro computing",
    "text and semigraphics display",
    "keyboard terminal",
    "serial terminal control"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与终端的串口通信。",
      "description_en": "Close serial communication with the terminal."
    },
    {
      "action_name": "auto-envoyer",
      "description": "向终端发送字符或控制序列。",
      "description_en": "Send characters or control sequences to the terminal."
    },
    {
      "action_name": "auto-recevoir",
      "description": "从终端读取一个接收到的字符。",
      "description_en": "Read a received character from the terminal."
    },
    {
      "action_name": "auto-recevoir_sequence",
      "description": "从终端读取一段完整的按键或控制序列。",
      "description_en": "Read a complete keypress or control sequence from the terminal."
    },
    {
      "action_name": "auto-appeler",
      "description": "向终端发送命令并等待其响应。",
      "description_en": "Send a command to the terminal and wait for its response."
    },
    {
      "action_name": "auto-definir_mode",
      "description": "设置终端的工作模式。",
      "description_en": "Set the terminal operating mode."
    },
    {
      "action_name": "auto-identifier",
      "description": "识别终端型号和可用特性。",
      "description_en": "Identify the terminal model and available features."
    },
    {
      "action_name": "auto-deviner_vitesse",
      "description": "自动检测终端的串口通信速率。",
      "description_en": "Automatically detect the terminal serial communication speed."
    },
    {
      "action_name": "auto-definir_vitesse",
      "description": "设置终端的串口通信速率。",
      "description_en": "Set the terminal serial communication speed."
    },
    {
      "action_name": "auto-configurer_clavier",
      "description": "配置终端键盘的工作方式。",
      "description_en": "Configure how the terminal keyboard operates."
    },
    {
      "action_name": "auto-couleur",
      "description": "设置后续字符的前景色和背景色。",
      "description_en": "Set the foreground and background colors for subsequent characters."
    },
    {
      "action_name": "auto-position",
      "description": "设置终端光标位置。",
      "description_en": "Set the terminal cursor position."
    },
    {
      "action_name": "auto-taille",
      "description": "设置后续字符的显示大小。",
      "description_en": "Set the display size of subsequent characters."
    },
    {
      "action_name": "auto-effet",
      "description": "启用或关闭字符显示效果。",
      "description_en": "Enable or disable character display effects."
    },
    {
      "action_name": "auto-curseur",
      "description": "显示或隐藏终端光标。",
      "description_en": "Show or hide the terminal cursor."
    },
    {
      "action_name": "auto-echo",
      "description": "启用或关闭键盘回显。",
      "description_en": "Enable or disable keyboard echo."
    },
    {
      "action_name": "auto-efface",
      "description": "清除终端屏幕的全部或部分内容。",
      "description_en": "Clear all or part of the terminal screen."
    },
    {
      "action_name": "auto-repeter",
      "description": "让终端重复显示指定字符。",
      "description_en": "Make the terminal repeat a specified character."
    },
    {
      "action_name": "auto-bip",
      "description": "让终端发出提示音。",
      "description_en": "Make the terminal emit a beep."
    },
    {
      "action_name": "auto-debut_ligne",
      "description": "将光标移到当前行的行首。",
      "description_en": "Move the cursor to the beginning of the current line."
    },
    {
      "action_name": "auto-supprime",
      "description": "删除光标后的字符或行内容。",
      "description_en": "Delete characters or line content after the cursor."
    },
    {
      "action_name": "auto-insere",
      "description": "在光标后插入字符或行内容。",
      "description_en": "Insert characters or line content after the cursor."
    },
    {
      "action_name": "auto-semigraphique",
      "description": "切换半图形显示模式。",
      "description_en": "Switch semigraphic display mode."
    },
    {
      "action_name": "auto-redefinir",
      "description": "重定义终端字符集中的字符图形。",
      "description_en": "Redefine character glyphs in the terminal character set."
    }
  ]
}

